function runtimeDefaults(d,device=store.settings.device,acc,engine){acc??=hardwareCatalog[device]?.accelerators[0]||'cpu';engine??=enginesFor(d,acc)[0]||'pytorch';return {modelId:d.model,device,accelerator:acc,engine,thinking:'default',context:'8192',maxOutput:'1024',overflow:'reject',temperature:'0.7',topP:'0.9',topK:'20',minP:'0',repeatPenalty:'1.05',stop:'',stream:true,kvPrecision:'auto',kvBudget:'8192',prefixCache:false,cacheScope:'task',prefillChunk:'512',chunkedPrefill:false,batchTokens:'2048',decodeBatch:'1',attention:'auto',graphs:false,splitPD:false,prefillEndpoint:'',decodeEndpoint:'',speculation:'off',draftModel:'',draftReady:false,specTokens:'3',draftPrecision:'auto',precision:'auto',memoryLimit:'80',cpuThreads:'8',gpuLayers:'auto',tensorParallel:'1',computeUnits:acc==='ane'?'CPU_AND_NE':acc==='cpu'?'CPU_ONLY':'CPU_AND_GPU',offload:'none',vaeTiling:false,vaeSlicing:false,compile:false,scheduler:'model-default',sampling:'20',speed:'1.0',cfg:'7',frames:'81',fps:'16',sampleRate:'24000',audioChunk:'200',streamAudio:false};}
function runtimeFor(d){if(!d.runtime||d.runtime.modelId!==d.model)d.runtime=runtimeDefaults(d,d.runtime?.device||store.settings.device);return d.runtime;}
function runtimeFeature(r,key){const e=r.engine;return ({prefix:['mlx','llama','vllm','sglang'].includes(e),chunk:['vllm','sglang'].includes(e),batch:['vllm','sglang'].includes(e),graphs:['vllm','sglang'].includes(e)&&r.accelerator==='cuda',split:['vllm','sglang'].includes(e),flash:['vllm','sglang','llama','transformers','diffusers'].includes(e)&&['cuda','rocm','metal','sycl'].includes(r.accelerator),compile:['transformers','diffusers','pytorch'].includes(e)&&['cuda','rocm'].includes(r.accelerator)})[key];}
